using Microsoft.AspNetCore.Mvc; using CursosMVC.Models; namespace CursosMVC.Controllers; public class CursoController:Controller{static List<Curso> cursos=new(){new Curso{Id=1,Nome="Curso 1",CargaHoraria=50,Modalidade="Online",Vagas=5,Valor=350}, new Curso{Id=2,Nome="Curso 2",CargaHoraria=60,Modalidade="Presencial",Vagas=10,Valor=400}, new Curso{Id=3,Nome="Curso 3",CargaHoraria=70,Modalidade="Online",Vagas=15,Valor=450}, new Curso{Id=4,Nome="Curso 4",CargaHoraria=80,Modalidade="Presencial",Vagas=0,Valor=500}, new Curso{Id=5,Nome="Curso 5",CargaHoraria=90,Modalidade="Online",Vagas=5,Valor=550}, new Curso{Id=6,Nome="Curso 6",CargaHoraria=100,Modalidade="Presencial",Vagas=10,Valor=600}, new Curso{Id=7,Nome="Curso 7",CargaHoraria=110,Modalidade="Online",Vagas=15,Valor=650}, new Curso{Id=8,Nome="Curso 8",CargaHoraria=120,Modalidade="Presencial",Vagas=0,Valor=700}, new Curso{Id=9,Nome="Curso 9",CargaHoraria=130,Modalidade="Online",Vagas=5,Valor=750}, new Curso{Id=10,Nome="Curso 10",CargaHoraria=140,Modalidade="Presencial",Vagas=10,Valor=800}}; public IActionResult Index()=>View(cursos); public IActionResult Disponiveis()=>View(cursos.Where(x=>x.Vagas>0)); public IActionResult Online()=>View(cursos.Where(x=>x.Modalidade=="Online")); public IActionResult Presenciais()=>View(cursos.Where(x=>x.Modalidade=="Presencial")); public IActionResult Resumo()=>View(cursos);}